<script setup>
import {ref} from 'vue';
import {useRouter} from 'vue-router';
import {useContext} from '../composables/context.js';
import {useAccess} from '../composables/access.js';
import {transferDocumentInvoice,documentationError,downloadFile} from '../services/documentation.js';
import {reportMoney as money,reportDate as date} from '../services/report-format.js';
defineProps({matches:{type:Array,default:()=>[]}});
const {selectedId}=useContext(),{can}=useAccess(),router=useRouter(),busy=ref(false),error=ref('');
async function transfer(row){if(busy.value||!can('accounting_write'))return;busy.value=true;error.value='';try{const saved=await transferDocumentInvoice({id:row.documentation_id,version:row.version},selectedId.value);await router.push({name:'invoices',query:{document_id:String(saved.id),exercise_id:String(saved.exercise_id)}});}catch(cause){error.value=documentationError(cause);}finally{busy.value=false;}}
async function original(row){if(busy.value)return;busy.value=true;error.value='';try{await downloadFile('/documentation/'+row.documentation_id+'/source',row.source_name);}catch(cause){error.value=documentationError(cause);}finally{busy.value=false;}}
</script>
<template><section v-if="matches.length" class="reconciliation-section pending-invoice-matches"><h2>Posibles facturas pendientes de Documentación</h2><p class="muted">Coincidencias por importe exacto y fecha próxima, referencia o nombre. Revisa la factura antes de confirmar su relación con el banco.</p><p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><article v-for="match in matches" :key="match.movement_id" class="panel invoice-match"><h3>{{ date(match.date) }} · {{ match.concept }} · {{ money(match.amount) }} €</h3><p v-if="match.ambiguous" class="notice">Hay varias facturas posibles para este movimiento.</p><div v-for="candidate in match.candidates" :key="candidate.documentation_id" class="invoice-match-candidate"><div><strong>{{ candidate.title }}</strong><p>{{ candidate.reference }}<span v-if="candidate.party"> · {{ candidate.party }}</span> · {{ money(candidate.total_amount) }} €</p><p class="muted">{{ candidate.basis }}</p><small>{{ candidate.source_name }}</small></div><div class="actions"><button class="button" :disabled="busy" @click="original(candidate)">Ver original</button><button class="button primary" :disabled="busy||!can('accounting_write')||!selectedId" @click="transfer(candidate)">Pasar a Facturas</button></div></div></article></section></template>
<style scoped>.invoice-match{padding:20px;margin:14px 0}.invoice-match h3{font-size:1rem;margin:0 0 12px;overflow-wrap:anywhere}.invoice-match-candidate{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:14px 0;border-top:1px solid #e0e6ed}.invoice-match-candidate>div{min-width:0}.invoice-match-candidate p{margin:7px 0;overflow-wrap:anywhere}.invoice-match-candidate small{overflow-wrap:anywhere}.invoice-match-candidate .actions{display:flex;gap:8px;flex-wrap:wrap;flex-shrink:0}@media(max-width:700px){.invoice-match-candidate{align-items:flex-start;flex-direction:column}.invoice-match{padding:16px}}</style>
